import {photos} from './photos.mjs';
import {homeSlides} from './home-content.mjs';
import {areas,categories,themes,filters,spots,courses,events,eventCategories,sortSpots} from './data.mjs';
import {DEFAULT_SITE_ORIGIN,isIndexablePath} from './site.mjs';
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label,cls='')=>`<a class="${cls}" href="${url}">${esc(label)}</a>`;
const searchLink=label=>`<a class="search-trigger" href="/search/" data-search-open>${esc(label)}</a>`;
const options=(values,all='すべて')=>`<option value="">${all}</option>`+Object.entries(Array.isArray(values)?Object.fromEntries(values.map(x=>[x,x])):values).map(([v,l])=>`<option value="${esc(v)}">${esc(l)}</option>`).join('');
const chips=(values,base,key='theme')=>`<div class="chips">${values.map(v=>link(`${base}?${key}=${encodeURIComponent(v)}`,v)).join('')}</div>`;
const section=(en,title,body,url,label='すべて見る →')=>`<section><div class="section-head"><div><div class="eyebrow">${en}</div><h2>${title}</h2></div>${url?link(url,label):''}</div>${body}</section>`;
const photoImage=(photo,name,cls='',eager=false,mobileSrc='',priority='high')=>{const load=eager?`loading="eager" fetchpriority="${esc(priority)}"`:'loading="lazy"';const img=`<img class="${esc(cls)}" src="${esc(photo?.src||'/assets/photos/unset.svg')}" alt="${esc(photo?.alt||name+'：写真未設定')}" width="${photo?.width||1280}" height="${photo?.height||800}" style="object-position:${esc(photo?.position||'50% 50%')}" ${load}>`;return mobileSrc?`<picture class="home-slide-picture"><source media="(max-width:390px)" srcset="${esc(mobileSrc)}">${img}</picture>`:img;};
const photoCredit=(photo,cls='')=>{if(!photo?.author&&!photo?.license)return '';const subject=photo.source?`<a href="${esc(photo.source)}" target="_blank" rel="noopener">${esc(photo.name)} / ${esc(photo.author)}</a>`:`${esc(photo.name)} / ${esc(photo.author)}`;const license=photo.licenseUrl?`<a href="${esc(photo.licenseUrl)}" target="_blank" rel="noopener">${esc(photo.license)}</a>`:esc(photo.license||'');const processing=photo.source?`<span>縮小・表示トリミング${String(photo.license||'').includes('SA')?'／写真の派生物も同ライセンス':''}</span>`:'';return `<p class="photo-credit ${cls}">写真：${subject}${license?' · '+license:''}${processing}</p>`};
const hero=(title,sub,compact=false,photo=null)=>`<div class="hero ${compact?'compact':''}">${photo?photoImage(photo,photo.name,'',true):''}<div class="inner"><div class="eyebrow">KOCHI · A JOURNEY TO REMEMBER</div><h1>${title}</h1><p>${sub}</p>${compact?'':`<form action="/search/" class="hero-search"><input name="q" aria-label="行きたい場所を検索" placeholder="行きたい場所を見つけよう" required><button aria-label="検索する">検索</button></form>`}</div>${photoCredit(photo,'photo-note')}</div>`;
export function spotCard(s,i){return `<article class="card spot-card ${i!==undefined?'rank-card':''}"><a href="/spots/${esc(s.slug)}/">${photoImage(s.photo,s.name)}${i!==undefined?`<span class="badge ${['gold','silver','bronze','other','other'][i]||'other'}">${i+1}</span>`:''}<div class="card-body"><span class="label">${esc(areas[s.area])} · ${esc(categories[s.category])}</span><h3>${esc(s.name)}</h3><p>${esc(s.catchphrase)}</p></div></a>${photoCredit(s.photo)}<div class="card-body vote-container"><button class="vote" data-vote="${esc(s.id)}" aria-pressed="false">♡ おすすめ <span>${Number(s.recommend_count)||0}</span></button></div></article>`}
const spotGrid=(items,rank=false)=>items.length?`<div class="grid spots-grid ${rank?'rank-grid':''}">${items.map((s,i)=>spotCard(s,rank?i:undefined)).join('')}</div>`:'<div class="empty"><h3>条件に合うスポットはありません。</h3><p>条件を変えて探すか、あなたのおすすめスポットを教えてください。</p><a class="button" href="/search/">条件を変えて探す</a> <a class="button" href="/suggest/">スポットを提案する</a></div>';
const courseCard=(c,i)=>`<article class="card course-card"><a href="/courses/${esc(c.slug)}/">${photoImage(c.photo,c.name)}${i!==undefined?`<span class="badge ${i===1?'silver':i===2?'bronze':i>2?'other':''}">${i+1}</span>`:''}<div class="card-body"><span class="label">${areas[c.area]} · ${esc(c.duration)}</span><h3>${esc(c.name)}</h3><p>${esc(c.theme)} / ${esc(c.transport)}</p></div></a>${photoCredit(c.photo)}</article>`;
const courseGrid=items=>`<div class="grid course-grid">${items.filter(Boolean).map(c=>courseCard(c)).join('')}</div>`;
let demoNotice='<div class="notice">掲載情報は確認できた内容をもとに更新しています。営業時間・料金・予約可否・交通状況などは変更される場合があるため、お出かけ前に各施設・事業者の公式情報をご確認ください。</div>';
const eventCard=e=>`<article class="card event-card">${e.image?`<a class="event-image-wrap" href="/events/${esc(e.slug)}/"><img class="event-image" src="${esc(e.image)}" alt="${esc(e.image_alt||e.name)}" loading="lazy">${e.image_note?`<span class="event-image-note">${esc(e.image_note)}</span>`:''}</a>`:''}<div class="card-body"><span class="label">${esc(e.category)} · ${esc(areas[e.area])}</span><h3>${link(`/events/${esc(e.slug)}/`,e.name)}</h3><p class="event-date">${esc(e.start_date)}${e.end_date!==e.start_date?' ～ '+esc(e.end_date):''}</p>${e.venue?`<p class="muted event-venue">${esc(e.venue)}</p>`:''}${e.is_demo?'<small>架空の表示サンプル・開催情報ではありません</small>':''}</div></article>`;
function homeEvents(){const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Tokyo'}).format(new Date());const month=today.slice(0,7);const current=events.filter(e=>!e.is_demo&&e.start_date<=month+'-31'&&e.end_date>=today).slice(0,3);return current.length?`<div class="grid">${current.map(eventCard).join('')}</div>`:'<div class="empty"><h3>現在表示できる開催情報はありません。</h3><p>今後の予定や過去の開催情報はイベント一覧から確認できます。</p><a class="button" href="/events/">イベント一覧を見る</a></div>';}
function homeSlider(){return `<section class="home-slider" data-carousel tabindex="0" aria-label="高知のおすすめ特集"><div class="home-slider-track">${homeSlides.map((slide,i)=>`<article class="home-slide" data-carousel-slide aria-hidden="${i?'true':'false'}">${photoImage(slide.photo,slide.title,'',true,i===0?'/assets/photos/hero-sup-mobile.png':'',i===0?'high':'low')}<div class="home-slide-shade"></div>${slide.note?`<p class="home-slide-note">${slide.note.split('\n').map(line=>`<span>${esc(line)}</span>`).join('')}</p>`:''}<div class="home-slide-content"><div class="eyebrow">${esc(slide.eyebrow||'KOCHI TRAVEL GUIDE')}</div><${i===0?'h1':'h2'} class="home-slide-title">${esc(slide.title)}</${i===0?'h1':'h2'}><p>${esc(slide.description)}</p>${link(slide.href,slide.label,'button')}</div>${photoCredit(slide.photo,'home-slide-credit')}</article>`).join('')}</div><div class="home-slider-controls"><button type="button" class="home-slider-arrow prev" data-carousel-prev aria-label="前の写真">‹</button><div class="home-slider-dots" aria-label="スライドを選択">${homeSlides.map((slide,i)=>`<button type="button" data-carousel-dot="${i}" aria-label="${i+1}枚目：${esc(slide.title)}" aria-current="${i===0?'true':'false'}"></button>`).join('')}</div><div class="home-slider-index" aria-label="スライド番号" aria-live="polite">${homeSlides.map((slide,i)=>`<span data-carousel-index="${i}" aria-current="${i===0?'true':'false'}">${String(i+1).padStart(2,'0')}</span>`).join('')}</div><button type="button" class="home-slider-arrow next" data-carousel-next aria-label="次の写真">›</button></div></section><div id="home-search-modal" class="home-search-modal" hidden role="dialog" aria-modal="true" aria-labelledby="home-search-title"><div class="home-search-dialog"><button type="button" class="home-search-close" data-search-close aria-label="検索を閉じる">×</button><section class="home-search-section" aria-label="旅先を検索"><form action="/search/" class="home-search"><div class="home-search-heading"><span class="home-search-icon" aria-hidden="true">⌕</span><span><small>行きたい高知が見つかる</small><strong id="home-search-title">スポットを検索</strong></span></div><div class="home-search-fields"><input id="home-search-input" name="q" aria-label="行きたい場所を検索" placeholder="キーワードで検索（例：桂浜、カツオ、仁淀川 など）"><select name="area" aria-label="エリア"><option value="">エリア</option>${options(areas).replace(/^<option value="">.*?<\/option>/,'')}</select><select name="category" aria-label="カテゴリ"><option value="">カテゴリ</option>${options(Object.fromEntries(visibleCategories())).replace(/^<option value="">.*?<\/option>/,'')}</select><select name="theme" aria-label="こだわり条件"><option value="">こだわり条件</option>${options(themes).replace(/^<option value="">.*?<\/option>/,'')}</select><button class="primary">⌕　検索する</button></div></form></section></div></div>`;}
const homeActivities=[
  ['SUP','仁淀川で水上散歩','/assets/photos/kochi-sup-hero.png','/activity/'],
  ['シーカヤック','海・川の景色を巡る','/assets/photos/sea-kayak.jpg','/activity/'],
  ['ラフティング','仲間と楽しむ爽快体験','/assets/photos/hero-rafting.png','/activity/'],
  ['サーフィン','太平洋の波を感じる','/assets/photos/kashiwajima.jpg','/activity/'],
  ['テントサウナ','仁淀川の自然の中でととのう','/assets/photos/tent-sauna-niyodo.png','/spots/sauna/'],
  ['龍河洞 冒険コース','洞窟の奥へ進むアドベンチャー','/assets/photos/ryugado.jpg','/spots/ryugado-adventure/'],
  ['猿田洞ケイビング','自然の洞窟をガイドと探検','/assets/photos/sarudado-caving.jpg','/spots/sarudado-caving/'],
  ['フォレストアドベンチャー','森の冒険で遊ぶ','/assets/photos/hero-forest-adventure.png','/activity/'],
  ['パラグライダー','空から高知を一望','/assets/photos/hero-paragliding.png','/activity/'],
  ['テントサウナ','自然の中でととのう','/assets/photos/tent-sauna-niyodo.png','/activity/']
];
const homeSceneSlugs=['kochi-castle','nikobuchi','kashiwajima','iokido','karst','muroto','ashizuri','monet'];
const homeScenes=()=>homeSceneSlugs.map(slug=>spots.find(s=>s.slug===slug)).filter(Boolean);
function homeActivityGrid(items=homeActivities){return `<div class="home-activity-grid">${items.map(([name,sub,src,href])=>`<a class="home-activity-card" href="${href}"><img src="${src}" alt="${name}" loading="lazy"><span class="home-activity-icon" aria-hidden="true">✦</span><strong>${name}</strong><small>${sub}</small></a>`).join('')}</div>`;}
function activityPopularGrid(items){return `<div class="home-activity-grid">${items.map(s=>`<a class="home-activity-card" href="/spots/${esc(s.slug)}/"><img src="${esc(s.photo?.src||'/assets/photos/unset.svg')}" alt="${esc(s.photo?.alt||s.name)}" loading="lazy"><span class="home-activity-icon" aria-hidden="true">✦</span><strong>${esc(s.name)}</strong><small>${esc(s.catchphrase)}</small></a>`).join('')}</div>`;}
function homeSceneStrip(){return `<div class="home-scene-strip">${homeScenes().map(s=>`<a class="home-scene-card" href="/spots/${esc(s.slug)}/"><img src="${esc(s.photo?.src||'/assets/photos/unset.svg')}" alt="${esc(s.photo?.alt||s.name)}" loading="lazy"><strong>${esc(s.name)}</strong><small>${esc(s.catchphrase)}</small></a>`).join('')}</div>`;}
function homeActivityRanking(){const items=sortSpots(spots.filter(s=>s.category==='activity'&&s.is_published!==false));return `<div class="home-activity-ranking">${items.map((s,i)=>`<a class="home-ranking-card" href="/spots/${esc(s.slug)}/"><span class="home-ranking-number rank-${i+1}">${i+1}</span><img src="${esc(s.photo?.src||'/assets/photos/unset.svg')}" alt="${esc(s.photo?.alt||s.name)}" loading="lazy"><strong>${esc(s.name)}</strong><small>${esc(s.catchphrase)}</small><span class="home-card-arrow" aria-hidden="true">›</span></a>`).join('')}</div>`;}
function activityHero(){return `<section class="activity-hero" aria-labelledby="activity-page-title"><img src="/assets/photos/kochi-sup-hero.png" alt="仁淀川で水上アクティビティを楽しむ風景" fetchpriority="high"><div class="activity-hero-shade"></div><div class="activity-hero-inner wrap"><div class="eyebrow">KOCHI ACTIVITY</div><h1 id="activity-page-title">アクティビティ</h1><p>高知の自然を全身で楽しむ、<br>心が動くアクティビティを見つけよう。</p></div></section>`;}
function activityFeaturedRanking(items){return `<div class="activity-featured-ranking">${items.slice(0,3).map((s,i)=>`<a class="activity-featured-card" href="/spots/${esc(s.slug)}/"><span class="activity-featured-rank rank-${i+1}">${i+1}</span><img src="${esc(s.photo?.src||'/assets/photos/unset.svg')}" alt="${esc(s.photo?.alt||s.name)}" loading="lazy"><span class="activity-featured-body"><small>${esc(s.catchphrase)}</small><strong>${esc(s.name)}</strong><span class="activity-featured-arrow" aria-hidden="true">›</span></span></a>`).join('')}</div>`;}
function activityFilter(){return `<form class="filterbar activity-filterbar" id="spot-filter"><label>エリア<select name="area">${options(areas)}</select></label><label>体験ジャンル<select name="theme">${options(filters.activity)}</select></label><button class="primary">絞り込む</button></form>`;}
function activityPage(){let list=sortSpots(spots.filter(s=>s.category==='activity'));return activityHero()+`<div class="wrap activity-page" data-ranking="activity">${activityFilter()}<section class="activity-ranking-section"><div class="section-head"><div><div class="eyebrow">ACTIVITY RANKING</div><h2>アクティビティランキング</h2></div>${link('#activity-vote-ranking','すべて見る →')}</div>${activityFeaturedRanking(list)}</section><section class="activity-popular-section"><div class="section-head"><div><div class="eyebrow">POPULAR ACTIVITIES</div><h2>人気のアクティビティ</h2></div></div>${activityPopularGrid(list)}</section><section class="activity-vote-section" id="activity-vote-ranking"><div class="section-head"><div><div class="eyebrow">VOTE RANKING</div><h2>みんなの投票ランキング</h2></div></div><p class="muted">実投票数順。まだ投票のない掲載スポットもご覧いただけます。</p><div id="rank-results">${spotGrid(list.slice(0,5),true)}</div><div id="more-results" hidden>${spotGrid(list.slice(5))}</div></section><section class="activity-theme-section"><div class="section-head"><div><div class="eyebrow">FIND YOUR FAVORITE</div><h2>テーマ・条件から探す</h2></div></div>${chips(filters.activity,'/activity/')}</section>${demoNotice}</div>`;}
const gourmetVisuals={myojinmaru:['/assets/photos/myojinmaru.png','夜に明かりが灯る明神丸 本店の外観'],yasube:['/assets/photos/yasube.png','赤提灯が灯る夜の屋台安兵衛'],hashimoto:['/assets/photos/hashimoto.png','橋本食堂の鍋焼きラーメン'],tanaka:['/assets/photos/tanaka.png','田中鮮魚店 漁師小屋の店内'],shirasu:['/assets/photos/shirasu.png','青空の下に建つ安芸しらす食堂 本店'],ice:['/assets/photos/ice.png','仁淀川を望むカフェの店内']};
const gourmetImage=s=>gourmetVisuals[s.slug]||['/assets/photos/course-katsuo-tataki.png','高知らしい料理'];
function gourmetHero(){return `<section class="gourmet-hero" aria-labelledby="gourmet-page-title"><img src="/assets/photos/course-katsuo-tataki.png" alt="藁焼き鰹塩たたき" fetchpriority="high"><div class="gourmet-hero-shade"></div><div class="gourmet-hero-inner wrap"><div class="eyebrow">KOCHI GOURMET</div><h1 id="gourmet-page-title">グルメ</h1><p>海・山・川の恵みがそろう高知で、<br>ここでしか味わえないおいしい出会いを。</p></div></section>`;}
function gourmetFilterChips(){const chipData=[['すべて',''],['海鮮','カツオ'],['郷土料理','郷土料理'],['カフェ','朝ごはん'],['スイーツ','スイーツ'],['市場・食堂','ひろめ市場'],['ランチ','ランチ']];return `<nav class="gourmet-filter-chips" aria-label="グルメのカテゴリー">${chipData.map(([label,theme],i)=>link(`/gourmet/${theme?`?theme=${encodeURIComponent(theme)}`:''}`,label,i===0?'active':'')).join('')}</nav>`;}
function gourmetFeaturedRanking(items){return `<div class="gourmet-featured-ranking">${items.slice(0,3).map((s,i)=>{const [src,alt]=gourmetImage(s);return `<a class="gourmet-featured-card" href="/spots/${esc(s.slug)}/"><span class="gourmet-featured-rank rank-${i+1}">${i+1}</span><img src="${src}" alt="${alt}" loading="lazy"><span class="gourmet-featured-body"><small>${esc(areas[s.area])}エリア</small><strong>${esc(s.name)}</strong><span>${esc(s.catchphrase)}</span><b aria-hidden="true">›</b></span></a>`}).join('')}</div>`;}
function gourmetPopular(items){return `<div class="gourmet-popular-grid">${items.map(s=>{const [src,alt]=gourmetImage(s);return `<a class="gourmet-popular-card" href="/spots/${esc(s.slug)}/"><img src="${src}" alt="${alt}" loading="lazy"><span><strong>${esc(s.name)}</strong><small>${esc(s.catchphrase)}</small><b aria-hidden="true">›</b></span></a>`}).join('')}</div>`;}
function gourmetCourses(){const visual={"kochi-gourmet":['/assets/photos/course-hirome-market.png','ひろめ市場のグルメ'],"east-drive":['/assets/photos/course-ocean-seafood.png','高知らしい海の幸']};return `<div class="gourmet-course-grid">${courses.filter(c=>c.theme==='グルメ').map(c=>{const [src,alt]=visual[c.slug]||[c.image,c.name];return `<a class="gourmet-course-card" href="/courses/${esc(c.slug)}/"><img src="${src}" alt="${alt}" loading="lazy"><span><small>${esc(c.duration)}コース · ${esc(areas[c.area])}</small><strong>${esc(c.name)}</strong><b aria-hidden="true">›</b></span></a>`}).join('')}</div>`;}
function gourmetPage(){const list=sortSpots(spots.filter(s=>s.category==='gourmet'));const gourmetNotice='<div class="notice">掲載情報は2026年10月1日時点で、各店舗の公式サイトまたは公的な観光情報を確認して更新しています。営業時間・定休日・価格などは変更される場合があるため、来店前に各店舗の公式情報をご確認ください。</div>';return gourmetHero()+`<div class="wrap gourmet-page" data-ranking="gourmet"><form class="filterbar gourmet-filterbar" id="spot-filter"><label>テーマ<select name="theme">${options(filters.gourmet)}</select></label><label>エリア<select name="area">${options(areas)}</select></label><button class="primary">絞り込む</button></form>${gourmetFilterChips()}<section class="gourmet-ranking-section"><div class="section-head"><div><h2>グルメランキング</h2><div class="eyebrow">GOURMET RANKING</div></div>${link('#gourmet-vote-ranking','すべて見る →')}</div>${gourmetFeaturedRanking(list)}</section><section class="gourmet-popular-section"><div class="section-head"><div><h2>人気のグルメ</h2><div class="eyebrow">POPULAR GOURMET</div></div></div>${gourmetPopular(list)}</section><section class="gourmet-courses-section"><div class="section-head"><div><h2>おすすめのグルメ体験</h2><div class="eyebrow">MODEL COURSES</div></div>${link('/courses/','すべて見る →')}</div>${gourmetCourses()}</section><section class="gourmet-vote-section" id="gourmet-vote-ranking"><div class="section-head"><div><h2>みんなの投票ランキング</h2><div class="eyebrow">VOTE RANKING</div></div></div><p class="muted">実投票数順。既存の投票順位を表示しています。</p><div id="rank-results">${spotGrid(list.slice(0,5),true)}</div><div id="more-results" hidden>${spotGrid(list.slice(5))}</div></section>${gourmetNotice}</div>`;}
const historyVisuals={
  'kochi-castle':['/assets/photos/kochi-castle-new.png','高知城の天守と石垣'],
  ryugado:['/assets/photos/ryugado-caving.png','ライトアップされた龍河洞の洞内'],
  yusuhara:['/assets/photos/yusuhara.jpg','梼原町のゆすはら座'],
  monet:['/assets/photos/monet.jpg','北川村「モネの庭」マルモッタン'],
  iokido:['/assets/photos/iokido.jpg','伊尾木洞のシダに覆われた岩壁'],
  muroto:['/assets/photos/muroto.jpg','室戸岬の岩礁と太平洋']
};
const historyImage=s=>historyVisuals[s.slug]||[s.photo?.src||'/assets/photos/unset.svg',s.photo?.alt||s.name+'：写真未設定'];
function historyHero(){return `<section class="history-hero" aria-labelledby="history-page-title"><img src="/assets/photos/kochi-castle-new.png" alt="高知城の天守と石垣" fetchpriority="high"><div class="history-hero-shade"></div><div class="history-hero-inner wrap"><div class="eyebrow">KOCHI HISTORY &amp; CULTURE</div><h1 id="history-page-title">歴史文化</h1><p>土佐の歴史と文化にふれ、<br>時をこえて受け継がれる魅力をたどる旅へ。</p></div></section>`;}
function historyFilterChips(){const chipData=[['城・史跡','歴史'],['龍馬・幕末','歴史'],['神社・寺院','歴史'],['博物館・資料館','雨の日'],['牧野植物園',''],['伝統文化','歴史']];return `<nav class="history-filter-chips" aria-label="歴史文化のカテゴリー">${chipData.map(([label,theme])=>link(`/sightseeing/${theme?`?theme=${encodeURIComponent(theme)}`:''}`,label)).join('')}</nav>`;}
function historyFeaturedRanking(items){return `<div class="history-featured-ranking">${items.map((s,i)=>{const [src,alt]=historyImage(s);return `<a class="history-featured-card" href="/spots/${esc(s.slug)}/"><span class="history-featured-rank rank-${i+1}">${i+1}</span><img src="${src}" alt="${alt}" loading="lazy"><span class="history-featured-body"><small>${esc(areas[s.area])}エリア</small><strong>${esc(s.name)}</strong><span>${esc(s.catchphrase)}</span><b aria-hidden="true">›</b></span></a>`}).join('')}</div>`;}
function historyPopular(items){return `<div class="history-popular-grid">${items.map(s=>{const [src,alt]=historyImage(s);return `<a class="history-popular-card" href="/spots/${esc(s.slug)}/"><img src="${src}" alt="${alt}" loading="lazy"><span><small>${esc(areas[s.area])} · 歴史文化</small><strong>${esc(s.name)}</strong><em>${esc(s.catchphrase)}</em><b aria-hidden="true">›</b></span></a>`}).join('')}</div>`;}
function historyCourses(){const visual={'kochi-classic':['/assets/photos/kochi-castle-new.png','高知城をめぐる旅']};const selected=courses.filter(c=>c.slug==='kochi-classic');return `<div class="history-course-grid">${selected.map(c=>{const [src,alt]=visual[c.slug];return `<a class="history-course-card" href="/courses/${esc(c.slug)}/"><img src="${src}" alt="${alt}" loading="lazy"><span><small>${esc(c.duration)}コース · ${esc(areas[c.area])}</small><strong>${esc(c.name)}</strong><b aria-hidden="true">›</b></span></a>`}).join('')}</div>`;}
function historyPage(){const historySlugs=['kochi-castle','chikurinji','kochi-castle-history-museum','sakamoto-ryoma-memorial-museum','makino-botanical-garden','shioe-tenmangu'];const list=sortSpots(spots.filter(s=>historySlugs.includes(s.slug)));const pick=slugs=>slugs.map(slug=>list.find(s=>s.slug===slug)).filter(Boolean);const featured=pick(['kochi-castle','chikurinji','sakamoto-ryoma-memorial-museum']);const popular=pick(historySlugs);return historyHero()+`<div class="wrap history-page" data-ranking="sightseeing" data-history-only="true"><form class="filterbar history-filterbar" id="spot-filter"><label>エリア<select name="area">${options(areas)}</select></label><label>テーマ・条件<select name="theme">${options(filters.sightseeing)}</select></label><button class="primary">絞り込む</button></form>${historyFilterChips()}<section class="history-ranking-section"><div class="section-head"><div><h2>歴史文化 人気スポットランキング</h2><div class="eyebrow">HISTORY &amp; CULTURE RANKING</div></div>${link('#history-vote-ranking','すべて見る →')}</div>${historyFeaturedRanking(featured)}</section><section class="history-popular-section"><div class="section-head"><div><h2>人気の歴史文化スポット</h2><div class="eyebrow">POPULAR HISTORY &amp; CULTURE</div></div></div>${historyPopular(popular)}</section><section class="history-courses-section"><div class="section-head"><div><h2>おすすめの歴史文化めぐり</h2><div class="eyebrow">MODEL COURSES</div></div>${link('/courses/','すべて見る →')}</div>${historyCourses()}</section><section class="history-vote-section" id="history-vote-ranking"><div class="section-head"><div><h2>みんなの投票ランキング</h2><div class="eyebrow">VOTE RANKING</div></div></div><p class="muted">実投票数順。既存の投票順位を表示しています。</p><div id="rank-results">${spotGrid(list.slice(0,5),true)}</div><div id="more-results" hidden>${spotGrid(list.slice(5))}</div></section>${demoNotice}</div>`;}
const homeCourseFeatures=[
  {slug:'niyodo-active',tags:['人気','体験'],departure:'高知市発',description:'シーカヤック、テントサウナ、川辺のカフェ、中津渓谷を楽しむアクティブな1日。',main:['/assets/photos/sea-kayak.jpg','透明な水面を上空から見下ろしたシーカヤック体験'],thumbs:[['/assets/photos/tent-sauna-niyodo.png','仁淀川沿いのテントサウナ'],['/assets/photos/ice.png','仁淀川を望む高知アイス売店 仁淀川カフェの店内'],['/assets/photos/nakatsu.jpg','中津渓谷の清流と岩場']]},
  {slug:'karst-drive',tags:['絶景','ドライブ'],departure:'高知市発',description:'四国カルストの高原景色と梼原の町並みをめぐる、ゆったり絶景ドライブ。',catchcopy:'雄大な高原と、\n山あいの町へ。',main:['/assets/photos/shikoku-karst-web.jpg','四国カルストの高原風景'],thumbs:[['/assets/photos/course-cloud-library.png','梼原の木造建築と図書館'],['/assets/photos/course-katsuo-tataki.png','高知名物のカツオのたたき'],['/assets/photos/hero-forest-adventure.png','森のアクティビティ']]},
  {slug:'niyodo-classic',tags:['空・山','キャンプ'],departure:'高知市発',description:'空からの絶景、仁淀ブルー、アウトドアを楽しむ1日コース。',main:['/assets/photos/course-classic-paragliding.png','空から高知の自然を望むパラグライダー'],thumbs:[['/assets/photos/course-classic-waterfall.png','仁淀ブルーの滝と渓谷'],['/assets/photos/course-classic-camping.png','自然の中で楽しむキャンプ'],['/assets/photos/course-classic-bridge.png','仁淀川に架かる橋と青い水面']]},
  {slug:'ocean-trip',tags:['人気','1泊2日'],departure:'高知市発',description:'柏島の青い海、海の幸、夕景をゆっくり楽しむ高知西部の1泊2日旅。',main:['/assets/photos/course-ocean-snorkeling.png','柏島の透明な海で楽しむシュノーケリング'],thumbs:[['/assets/photos/course-ocean-seafood.png','高知西部の海の幸'],['/assets/photos/course-ocean-sunset.png','海に沈む夕日'],['/assets/photos/course-ocean-beach.png','柏島の透明な海と白い浜辺']]}
];
const visibleCategories=()=>Object.entries(categories).filter(([key])=>spots.some(s=>s.category===key&&s.is_published!==false));
const recentlyVerifiedSpots=()=>[...spots].filter(s=>s.last_verified_at).sort((a,b)=>String(b.last_verified_at).localeCompare(String(a.last_verified_at))).slice(0,3);
function homeCourseGrid(){return `<div class="home-course-grid">${homeCourseFeatures.map(feature=>{const course=courses.find(c=>c.slug===feature.slug);if(!course)return '';return `<article class="home-course-card"><a class="home-course-media" href="/courses/${esc(course.slug)}/" aria-label="${esc(course.name)}の詳細を見る"><img class="home-course-main" src="${esc(feature.main[0])}" alt="${esc(feature.main[1])}" loading="lazy">${feature.catchcopy?`<span class="home-course-catchcopy">${feature.catchcopy.split(/\n/).map(line=>esc(line)).join('<br>')}</span>`:''}<div class="home-course-thumbs">${feature.thumbs.map(([src,alt])=>`<img src="${esc(src)}" alt="${esc(alt)}" loading="lazy">`).join('')}</div></a><div class="home-course-body"><div class="home-course-topline"><h3>${link(`/courses/${esc(course.slug)}/`,course.name)}</h3><div class="home-course-tags">${feature.tags.map(tag=>`<span>${esc(tag)}</span>`).join('')}</div></div><dl class="home-course-meta"><div><dt>出発</dt><dd>${esc(feature.departure)}</dd></div><div><dt>日程</dt><dd>${esc(course.duration)}</dd></div><div><dt>エリア</dt><dd>${esc(areas[course.area])}</dd></div></dl><div class="home-course-footer"><p>${esc(feature.description)}</p>${link(`/courses/${esc(course.slug)}/`,'コース詳細を見る　→','home-course-link')}</div></div></article>`}).join('')}</div>`;}
const homeSearchCategories=[
  ['アクティビティ','♢','/activity/','blue'],['体験','✦','/experience/','green'],['グルメ','♜','/gourmet/','green'],['歴史文化','⌂','/sightseeing/','gold'],['イベント','✦','/events/','blue'],['絶景','◇','/search/?q=%E7%B5%B6%E6%99%AF','purple']
];
const homeSearchSubcategories=[
  ['仁淀ブルー','♒','/search/?q=%E4%BB%81%E6%B7%80%E3%83%96%E3%83%AB%E3%83%BC'],['絶景','◇','/search/?q=%E7%B5%B6%E6%99%AF'],['川遊び','≈','/activity/'],['ものづくり','✦','/experience/?theme=%E6%96%87%E5%8C%96%E3%83%BB%E3%82%82%E3%81%AE%E3%81%A5%E3%81%8F%E3%82%8A%E4%BD%93%E9%A8%93'],['グルメ','♜','/gourmet/'],['雨の日','☂','/experience/?theme=%E9%9B%A8%E3%81%AE%E6%97%A5']
];
function homeCategorySearch(){return `<section class="home-category-search" aria-labelledby="home-category-search-title"><div class="home-category-search-inner"><div class="home-category-search-heading"><div class="eyebrow">FIND YOUR KOCHI</div><h2 id="home-category-search-title">高知をカテゴリーから探す</h2><p>気になるテーマから、行きたい場所を見つけよう。</p></div><form class="home-category-keyword" action="/search/" method="get" data-home-keyword-form><span aria-hidden="true">⌕</span><input name="q" placeholder="興味のあるキーワード" aria-label="興味のあるキーワード"><button type="submit" data-search-open>検索</button></form><div class="home-category-main">${homeSearchCategories.map(([label,icon,href,tone])=>`<a class="home-category-card ${tone}" href="${href}"><span class="home-category-icon" aria-hidden="true">${icon}</span><strong>${label}</strong><span class="home-category-arrow" aria-hidden="true">›</span></a>`).join('')}</div><div class="home-category-sub">${homeSearchSubcategories.map(([label,icon,href])=>`<a class="home-category-subcard" href="${href}"><span class="home-category-subicon" aria-hidden="true">${icon}</span><strong>${label}</strong><span aria-hidden="true">›</span></a>`).join('')}</div></div></section>`;}
function home(){return homeSlider()+homeCategorySearch()+`<div class="home-content wrap">`+section('MODEL COURSE','おすすめモデルコース',homeCourseGrid(),'/courses/','すべて見る →')+section('POPULAR RANKING','人気アクティビティランキング',homeActivityRanking(),'/activity/','すべて見る →')+`<section class="home-scene-section"><div class="section-head"><div><div class="eyebrow">SCENIC SPOT</div><h2>景色・名所から探す</h2></div>${link('/sightseeing/','すべて見る →')}</div>${homeSceneStrip()}</section>`+section('CATEGORIES','高知を楽しむカテゴリー一覧',`<div class="home-category-chips">${visibleCategories().map(([k,v])=>link('/'+k+'/',v+' →')).join('')}</div>`)+`<section class="home-pickup-section"><div class="home-pickup-label"><div class="eyebrow">PICK UP</div><h2>おすすめピックアップ</h2></div><div class="feature"><div class="eyebrow">SKY &amp; NIYODO BLUE</div><h3>空と仁淀ブルーを楽しむ1日。</h3><p>空からの絶景、仁淀ブルー、キャンプ。<br>高知の自然をたっぷり楽しむモデルコースをご紹介。</p>${link('/courses/niyodo-classic/','コースを見る →','button')}</div></section>`+`<div class="home-bottom-grid"><section><div class="section-head"><div><div class="eyebrow">EVENT</div><h2>今週・今月のイベント</h2></div>${link('/events/','すべて見る →')}</div>${homeEvents()}</section><section><div class="section-head"><div><div class="eyebrow">RECENTLY VERIFIED</div><h2>最近情報を確認したスポット</h2></div>${link('/search/','すべて見る →')}</div>${spotGrid(recentlyVerifiedSpots())}</section></div>`+demoNotice+'</div>'}
const featureCards=[
  ['空と仁淀ブルーキャンプ1日コース','空からの絶景、仁淀ブルー、キャンプを楽しむ高知のアウトドア旅。','/assets/photos/course-niyodo-sky-camp.png','/courses/niyodo-classic/','SKY & NIYODO BLUE'],
  ['柏島・足摺の海をめぐる','柏島の青い海と足摺岬の絶景を楽しむ、高知西部の1泊2日旅。','/assets/photos/course-ocean-trip-collage.png','/courses/ocean-trip/','KASHIWAJIMA'],
  ['歴史文化にふれる','高知城、竹林寺、龍馬。高知の歴史を歩いてたどる。','/assets/photos/kochi-castle-new.png','/sightseeing/','HISTORY'],
  ['自然の中で体験する','シーカヤック、テントサウナ、洞窟探検。高知の自然を全身で楽しむ体験へ。','/assets/photos/sea-kayak.jpg','/activity/','ACTIVITY'],
  ['高知の味を楽しむ','カツオ、屋台、しらす、川辺のスイーツ。旅の目的になる高知グルメ。','/assets/photos/course-katsuo-tataki.png','/gourmet/','GOURMET'],
  ['季節のイベントを楽しむ','祭り、花、食、地域イベント。旅の日に重なる高知の今を探す。','/assets/photos/event-yosakoi.png','/events/','EVENT']
];
function featuresPage(){return hero('高知を、テーマで旅する。','景色、体験、歴史、食。気になるテーマから次の旅を見つけよう。',true,photos.nikobuchi)+`<div class="wrap features-page"><section><div class="section-head"><div><div class="eyebrow">FEATURES</div><h2>おすすめ特集</h2></div></div><div class="features-grid">${featureCards.map(([title,desc,img,href,en])=>`<article class="feature-card"><a href="${href}"><div class="feature-card-media"><img src="${img}" alt="${title}" loading="lazy"><span>${en}</span></div><div class="feature-card-body"><h3>${title}</h3><p>${desc}</p><b>特集を見る　→</b></div></a></article>`).join('')}</div></section><section class="features-cta"><div><div class="eyebrow">PLAN YOUR TRIP</div><h2>行き先が決まったら、旅の流れをつくる。</h2><p>モデルコースなら、立ち寄りスポットを順番に見ながら旅を組み立てられます。</p></div>${link('/courses/','モデルコースを見る →','button')}</section></div>`;}
const areaFeatures={
  kochi_city:{title:'高知市内',en:'KOCHI CITY',desc:'高知城、街歩き、カツオ、屋台。初めての高知旅にも組み込みやすい中心エリア。',photo:'kochi-castle',tags:['歴史文化','グルメ','街歩き']},
  east:{title:'東部',en:'EAST KOCHI',desc:'室戸の海岸線、伊尾木洞、モネの庭。海と自然を感じるドライブ旅へ。',photo:'muroto',tags:['絶景','自然','ドライブ']},
  west:{title:'西部',en:'WEST KOCHI',desc:'柏島、足摺、四国カルスト。青い海と大地のスケールを楽しむエリア。',photo:'kashiwajima',tags:['海','絶景','1泊旅']},
  north_niyodo:{title:'北部・仁淀川',en:'NIYODO & NORTH',desc:'仁淀ブルー、渓谷、川遊び、山の景色。自然の中で過ごす時間を楽しむ。',photo:'nikobuchi',tags:['仁淀ブルー','川遊び','自然']}
};
function areaLanding(){return hero('高知を、エリアから旅する。','海、川、街、山。4つのエリアから、行きたい高知を見つけよう。',true,photos.kashiwajima)+`<div class="wrap area-landing"><section><div class="section-head"><div><div class="eyebrow">AREA GUIDE</div><h2>4つのエリアから探す</h2></div></div><div class="area-guide-grid">${Object.entries(areaFeatures).map(([key,a])=>`<article class="area-guide-card"><a href="/area/${key.replaceAll('_','-')}/"><div class="area-guide-media">${photoImage(photos[a.photo],a.title)}<span>${esc(a.en)}</span></div><div class="area-guide-body"><h3>${esc(a.title)}</h3><p>${esc(a.desc)}</p><div class="area-guide-tags">${a.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div><b>このエリアを見る　→</b></div></a></article>`).join('')}</div></section></div>`;}
function areaPage(area){const a=areaFeatures[area];const areaSpots=sortSpots(spots.filter(s=>s.area===area));const areaCourses=courses.filter(c=>c.area===area);return hero(esc(a.title)+'を旅する',esc(a.desc),true,photos[a.photo])+`<div class="wrap area-detail"><section class="area-intro"><div><div class="eyebrow">${esc(a.en)}</div><h2>${esc(a.title)}の旅</h2><p>${esc(a.desc)}</p></div><div class="area-guide-tags">${a.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div></section>${section('SPOTS','おすすめスポット',spotGrid(areaSpots))}${section('COURSES','このエリアのモデルコース',areaCourses.length?courseGrid(areaCourses):'<div class="empty"><h3>このエリアのモデルコースは現在ありません。</h3><p>おすすめスポットを参考に旅を組み立ててみてください。</p><a class="button" href="/courses/">モデルコース一覧を見る</a></div>')}<section class="area-switch"><div class="section-head"><div><div class="eyebrow">OTHER AREAS</div><h2>ほかのエリアも見る</h2></div>${link('/area/','エリア一覧 →')}</div><div class="area-switch-grid">${Object.entries(areaFeatures).filter(([key])=>key!==area).map(([key,x])=>link('/area/'+key.replaceAll('_','-')+'/',x.title+' →')).join('')}</div></section></div>`;}
function ranking(category){if(category==='activity')return activityPage();if(category==='gourmet')return gourmetPage();if(category==='sightseeing')return historyPage();let list=sortSpots(spots.filter(s=>s.category===category));return hero(`${categories[category]}ランキング`,'みんなの「おすすめ」で見つける、高知の楽しみ方。',true)+`<div class="wrap" data-ranking="${category}"><form class="filterbar" id="spot-filter"><label>エリア<select name="area">${options(areas)}</select></label><label>テーマ・条件<select name="theme">${options(filters[category]||['絶景','子連れ','雨の日','定番','穴場'])}</select></label><button class="primary">絞り込む</button></form><p class="muted">実投票数 → 同票時は初期順位。すべての掲載スポットは0票から。</p>${section('TOP PICKS','総合 TOP5',`<div id="rank-results">${spotGrid(list.slice(0,5),true)}</div>`)}${section('FIND YOUR FAVORITE','テーマ・条件から探す',chips(filters[category]||['絶景','子連れ','雨の日'],`/${category}/`))}${section('MORE TO DISCOVER','みんなのおすすめ',`<div id="more-results">${spotGrid(list.slice(5))}</div>`)}${section('NEW','新着スポット',spotGrid([...list].reverse().slice(0,3)))}${section('TRAVEL NOTES','おすすめ記事・特集',`<div class="feature"><h3>スポットをつなげて、ひとつの旅に。</h3>${link('/courses/','モデルコースから探す →','button')}</div>`)}${demoNotice}</div>`}
function coursesPage(){return hero('高知をめぐる、<br>とっておきのコース。','気になるエリアとテーマから、あなたに合う旅を。',true,photos.karst)+`<div class="wrap"><form id="course-filter" class="filterbar"><label>エリア<select name="area">${options(areas)}</select></label><label>テーマ<select name="theme">${options(themes)}</select></label><label>日数<select name="duration">${options(['半日','1日','1泊2日','2泊3日'])}</select></label><button class="primary">絞り込む</button></form><p id="result-count">10件のモデルコース</p><div id="course-results">${courseGrid(courses)}</div>${demoNotice}</div>`}
function courseDetail(c){const items=(c.schedule?.length?c.schedule:c.stops.map((slug,i)=>({slug,time:'',day:c.dayBreaks?.[i]||''})));return hero(esc(c.name),'寄り道まで楽しむ、高知の旅。',true,c.photo)+`<div class="wrap"><div class="summary"><span>所要時間：${esc(c.duration)}</span><span>移動：${esc(c.transport)}</span><span>対象：${esc(c.audience)}</span><span>季節：${esc(c.season)}</span></div><button class="save-trip" data-save-course="${esc(c.slug)}" aria-pressed="false">♡ コースを保存</button><div class="notice">時刻はモデルプランの目安です。予約枠・道路状況・営業時間・季節営業に合わせて調整し、出発前に公式情報と地図で最新状況をご確認ください。</div><div class="two-col"><section><h2>旅のスケジュール</h2><div class="timeline">${items.map((item,i)=>{const spot=item.slug?spots.find(x=>x.slug===item.slug):null;const day=item.day?`<div class="course-day-label">${esc(item.day)}</div>`:'';if(!spot)return `${day}<article class="stop course-free-stop"><div class="course-time">${esc(item.time||'')}</div><span class="eyebrow">PLAN</span><h3>${esc(item.title||'自由時間')}</h3>${item.note?`<p>${esc(item.note)}</p>`:''}</article>`;const mins=c.stopMinutes?.[item.slug]||90;return `${day}<article class="stop"><div class="course-time">${esc(item.time||'')}</div>${photoImage(spot.photo,spot.name,'stop-photo')}<span class="eyebrow">STOP ${String(i+1).padStart(2,'0')}</span><h3>${link('/spots/'+item.slug+'/',spot.name)}</h3>${photoCredit(spot.photo)}<p>${esc(spot.catchphrase)}</p><p class="muted">滞在の目安：約${mins}分${i?' / 移動時間は地図で最新経路をご確認ください':''}</p>${item.note?`<p class="course-note">${esc(item.note)}</p>`:''}</article>`}).join('')}</div></section><aside><h2>地図でルートを見る</h2><p>各スポットの場所と移動時間を確認できます。</p>${link('https://www.google.com/maps/dir/'+c.stops.map(slug=>encodeURIComponent((spots.find(s=>s.slug===slug)?.name||slug)+' 高知')).join('/'),'Google Mapsでルートを見る ↗','button')}<h3>立ち寄りグルメ</h3>${c.stops.filter(slug=>spots.find(s=>s.slug===slug)?.category==='gourmet').map(slug=>`<p>${link('/spots/'+slug+'/',spots.find(s=>s.slug===slug).name)}</p>`).join('')||'<p>周辺の飲食店もチェック。</p>'+link('/gourmet/','グルメ一覧 →')}<h3>旅の注意点</h3><p>天候・増水・通行規制を事前に確認してください。体験は開催事業者への予約確認が必要です。自然環境と地域のルールを大切に。</p></aside></div>${demoNotice}</div>`}
function spotFacts(s){const meaningful=v=>v!==undefined&&v!==null&&String(v).trim()!==''&&!['未確認','確認中'].includes(String(v).trim());const items=[];if(meaningful(s.address))items.push(['住所',s.address]);if(meaningful(s.opening_hours))items.push(['営業時間',s.opening_hours]);if(meaningful(s.closed_days))items.push(['定休日',s.closed_days]);if(meaningful(s.price_text))items.push(['料金',s.price_text]);if(meaningful(s.parking_text))items.push(['駐車場',s.parking_text]);if(meaningful(s.access))items.push(['アクセス',s.access,true]);if(meaningful(s.phone))items.push(['電話',`<a class="spot-fact-link" href="tel:${esc(String(s.phone).replace(/[^0-9+]/g,''))}">${esc(s.phone)}</a>`,false,true]);if(meaningful(s.official_url))items.push(['公式サイト',`<a class="spot-fact-link" href="${esc(s.official_url)}" target="_blank" rel="noopener">公式サイトを開く ↗</a>`,false,true]);if(meaningful(s.last_verified_at))items.push(['最終情報確認日',s.last_verified_at]);if(!items.length)return '<div class="notice spot-info-pending">基本情報は確認できた項目から順次掲載しています。お出かけ前に施設・体験事業者の公式情報をご確認ください。</div>';return `<div class="spot-facts">${items.map(([label,value,wide,html])=>`<div class="spot-fact ${wide?'wide':''}"><span class="spot-fact-label">${esc(label)}</span><div class="spot-fact-value">${html?value:esc(value)}</div></div>`).join('')}</div>`;}
function spotDetail(s){let rank=sortSpots(spots.filter(x=>x.category===s.category)).findIndex(x=>x.id===s.id)+1;return `<div class="wrap"><section><p class="muted">${link('/'+s.category+'/',categories[s.category])} / ${areas[s.area]}</p>${photoImage(s.photo,s.name,'detail-photo',true)}${photoCredit(s.photo)}<div class="eyebrow">${areas[s.area]}${s.municipality&&s.municipality!=='確認中'?' · '+esc(s.municipality):''}</div><h1>${esc(s.name)}</h1><h2>${esc(s.catchphrase)}</h2><p>現在順位：<span id="current-rank">${rank}</span> / 初期順位：${s.initial_rank}（${categories[s.category]}）</p><div style="max-width:320px"><button class="vote" data-vote="${s.id}" aria-pressed="false">♡ おすすめ <span>0</span></button></div><div class="chips"><button class="save-trip" data-save-spot="${esc(s.slug)}" aria-pressed="false">♡ 行ってみたい</button></div>${s.description&& !s.description.startsWith('初期掲載候補です。')?`<p class="spot-description">${esc(s.description)}</p>`:''}<div class="spot-info-head"><div class="eyebrow">INFORMATION</div><h2>基本情報</h2></div>${spotFacts(s)}<div class="spot-info-actions">${link('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(s.name+' 高知'),'地図で場所を見る ↗','button primary')}${link('/correction/?spot='+s.slug,'情報の修正を提案','button')}</div></section>${section('HIGHLIGHTS','このスポットのポイント',`<div class="spot-highlights"><div class="spot-highlight-copy"><p>${esc(s.catchphrase)}</p><div class="chips">${(s.tags||[]).map(tag=>`<span>${esc(tag)}</span>`).join('')}</div></div><div class="spot-highlight-meta"><div><small>エリア</small><strong>${esc(areas[s.area])}</strong></div><div><small>カテゴリ</small><strong>${esc(categories[s.category])}</strong></div>${s.municipality&&s.municipality!=='確認中'?`<div><small>市町村</small><strong>${esc(s.municipality)}</strong></div>`:''}</div></div><div class="spot-check"><strong>行く前にチェック</strong><p>営業時間・料金・定休日・予約可否などは変更される場合があります。来訪前に公式情報をご確認ください。</p>${s.last_verified_at?`<small>サイト最終情報確認日：${esc(s.last_verified_at)}</small>`:''}</div>`)}${section('NEARBY','同じエリアのおすすめ',spotGrid(spots.filter(x=>x.area===s.area&&x.id!==s.id).slice(0,3)))}${section('RELATED COURSES','関連モデルコース',courseGrid(courses.filter(c=>c.stops.includes(s.slug))))}${demoNotice}</div>`}
function eventsPage(){const visibleEvents=events.filter(e=>!e.is_demo);return hero('高知の今に、会いにいく。','祭り、食、自然。旅の日程に合わせて見つけよう。',true)+`<div class="wrap"><form id="event-filter" class="filterbar"><label>日程<select name="period">${options(['今日','今週','今月','開催中','これから'])}</select></label><label>カテゴリ<select name="category">${options(eventCategories)}</select></label><button class="primary">絞り込む</button></form><div class="notice">2026年10月1日時点で、公式サイト・公的な観光情報から確認できたイベントを掲載しています。終了したイベントも2026年の記録として表示しています。開催内容は変更・中止になる場合があるため、お出かけ前に各イベントの公式情報をご確認ください。</div><section id="event-results">${visibleEvents.length?`<div class="grid">${visibleEvents.map(eventCard).join('')}</div>`:'<div class="empty">現在表示できる開催情報はありません。</div>'}</section><p>常設・予約制のものは ${link('/activity/','アクティビティ一覧','subtle-link')} / ${link('/experience/','体験一覧','subtle-link')} から。</p></div>`}
function eventDetail(e){return hero(esc(e.name),'イベント詳細',true)+`<div class="wrap"><section><div class="notice">${esc(e.description)}</div><dl class="facts"><dt>日程</dt><dd>${esc(e.start_date)}${e.end_date!==e.start_date?' ～ '+esc(e.end_date):''}</dd><dt>開催時間</dt><dd>${esc(e.time||'公式情報をご確認ください')}</dd><dt>エリア</dt><dd>${esc(areas[e.area])}</dd><dt>カテゴリ</dt><dd>${esc(e.category)}</dd><dt>会場</dt><dd>${esc(e.venue||'公式情報をご確認ください')}</dd><dt>料金</dt><dd>${esc(e.fee||'公式情報をご確認ください')}</dd><dt>問い合わせ</dt><dd>${esc(e.phone||'公式情報をご確認ください')}</dd></dl>${e.official_url?link(e.official_url,'公式サイトで最新情報を確認 ↗','button')+' ':''}${link('/events/','イベント一覧へ','button')}</section></div>`}
const guideItems=[
  ['はじめての高知旅','まずは行きたい場所を1〜2個決めて、周辺スポットやモデルコースから旅を広げるのがおすすめです。','/search/','スポットを探す →','START'],
  ['エリアから決める','高知市内・東部・西部・北部・仁淀川の4エリアから、旅の方向を決められます。','/area/','エリアから探す →','AREA'],
  ['移動を組み立てる','離れたスポットを詰め込みすぎず、同じエリアをまとめて回ると予定を立てやすくなります。','/courses/','モデルコースを見る →','ROUTE'],
  ['天候と服装を確認','川・海・山の体験は天候の影響を受けます。出発前に天気と各施設の最新案内を確認してください。','/activity/','体験を確認する →','WEATHER'],
  ['イベントを旅に足す','旅行日に重なる祭りや季節イベントがあれば、旅程に加えるとその時期ならではの高知を楽しめます。','/events/','イベントを見る →','EVENT'],
  ['食事も先にチェック','人気店や営業時間が限られる店は、行きたいスポットと一緒に食事候補も決めておくと安心です。','/gourmet/','グルメを探す →','GOURMET']
];
function guidePage(){return hero('高知旅行の、お役立ち情報。','旅の組み立て方から、エリア・移動・天候・イベントまで。出発前に確認したいポイントをまとめました。',true,photos.karst)+`<div class="wrap guide-page"><section><div class="section-head"><div><div class="eyebrow">TRAVEL TIPS</div><h2>旅の前にチェック</h2></div></div><div class="guide-grid">${guideItems.map(([title,desc,href,cta,en])=>`<article class="guide-card"><div class="eyebrow">${en}</div><h3>${title}</h3><p>${desc}</p>${link(href,cta,'subtle-link')}</article>`).join('')}</div></section><section class="guide-plan"><div class="section-head"><div><div class="eyebrow">3 STEPS</div><h2>迷ったら、この順番で。</h2></div></div><div class="guide-steps"><article><span>01</span><h3>行きたい場所を探す</h3><p>景色、グルメ、体験など気になるテーマから候補を見つけます。</p>${link('/search/','スポットを探す →')}</article><article><span>02</span><h3>エリアをまとめる</h3><p>同じエリアのスポットをまとめると、旅程を組みやすくなります。</p>${link('/area/','エリアを見る →')}</article><article><span>03</span><h3>コースで流れを確認</h3><p>モデルコースを参考に、立ち寄る順番や移動の流れを確認します。</p>${link('/courses/','モデルコースを見る →')}</article></div></section><section class="guide-note"><div><div class="eyebrow">BEFORE YOU GO</div><h2>出発前の最終確認</h2><p>営業時間・定休日・料金・予約可否・イベント内容・天候による催行状況は変更される場合があります。来訪前に各施設や主催者の公式情報をご確認ください。</p></div>${link('/events/','開催中のイベントを見る →','button')}</section></div>`;}
function savedTripsPage(){return hero('保存した旅','行ってみたいスポットと、気になるモデルコースをこの端末に保存できます。',true,photos.nikobuchi)+`<div class="wrap saved-trips-page"><div class="notice">保存内容はこのブラウザにだけ保存されます。会員登録や個人情報の入力は不要です。</div><section><div class="section-head"><div><div class="eyebrow">SAVED SPOTS</div><h2>行ってみたいスポット</h2></div></div><div id="saved-spots"><div class="empty">まだ保存したスポットはありません。</div></div></section><section><div class="section-head"><div><div class="eyebrow">SAVED COURSES</div><h2>保存したモデルコース</h2></div></div><div id="saved-courses"><div class="empty">まだ保存したモデルコースはありません。</div></div></section></div>`;}
function searchPage(){const quick=['仁淀ブルー','絶景','グルメ','子連れ','歴史文化','雨の日'];return hero('高知の旅を探す','スポット名、エリア、テーマから、行きたい場所を見つけよう。',true,photos.nikobuchi)+`<div class="wrap search-page"><section><div class="search-page-head"><div><div class="eyebrow">FIND YOUR KOCHI</div><h2>条件からスポットを探す</h2><p>キーワードだけでも、エリア・カテゴリ・こだわり条件との組み合わせでも検索できます。</p></div></div><form class="search-advanced" id="search-form"><div class="search-advanced-grid"><label class="search-keyword">キーワード<input name="q" aria-label="スポット・コースを検索" placeholder="例：仁淀ブルー、カツオ、雨の日"></label><label>エリア<select name="area">${options(areas,'すべてのエリア')}</select></label><label>カテゴリ<select name="category">${options(Object.fromEntries(visibleCategories()),'すべてのカテゴリ')}</select></label><label>こだわり<select name="theme">${options(themes,'すべてのこだわり')}</select></label><button class="primary" type="submit">検索する</button></div></form><div class="search-quick"><span>人気の検索</span>${quick.map(q=>link('/search/?q='+encodeURIComponent(q),q)).join('')}</div><div id="search-summary" class="search-summary" aria-live="polite"></div><div id="search-results"></div></section></div>`;}
function field(name,label,required=false,type='text'){return `<label>${label}${required?'<span class="required">必須</span>':''}<input name="${name}" type="${type}" ${required?'required':''} maxlength="${type==='url'?2000:300}"></label>`}
function formPage(kind){const suggest=kind==='suggest';return `<div class="wrap"><section><div class="eyebrow">HELP US DISCOVER KOCHI</div><h1>${suggest?'おすすめスポットを教えてください':'情報の修正を提案'}</h1><p>ご提案は運営が確認してから反映します。</p><div class="notice" id="form-mode">接続状態を確認しています。</div><form class="form" id="request-form" data-kind="${kind}">${suggest?field('name','店名・施設名',true)+`<div class="form-grid"><label>カテゴリ<span class="required">必須</span><select name="category" required>${options(categories,'選択してください')}</select></label><label>エリア<span class="required">必須</span><select name="area" required>${options(areas,'選択してください')}</select></label></div>`+field('municipality','市町村',true)+`<label>おすすめ理由<span class="required">必須</span><textarea name="reason" required maxlength="3000"></textarea></label><div class="form-grid">${[['address','住所'],['official_url','公式サイト','url'],['instagram','Instagram','url'],['x_url','X','url'],['phone','電話','tel'],['google_maps_url','Google Maps URL','url'],['menu','おすすめメニュー'],['nickname','ニックネーム'],['email','メール','email']].map(([n,l,t])=>field(n,l,false,t)).join('')}</div><label>補足<textarea name="notes" maxlength="3000"></textarea></label>`:`<label>対象スポット<span class="required">必須</span><select name="spot_id" required>${options(Object.fromEntries(spots.map(s=>[s.id,s.name])),'選択してください')}</select></label><label>修正対象<span class="required">必須</span><select name="target" required>${options(['営業時間','定休日','住所','電話','料金','駐車場','公式URL','店名/施設名','閉店/休業','写真','その他'],'選択してください')}</select></label><label>修正内容・確認元<span class="required">必須</span><textarea name="reason" maxlength="3000" required></textarea></label>${field('email','メール（任意）',false,'email')}`}<p class="footnote">入力内容は確認・連絡のために使用します。${link('/privacy/','プライバシー方針','subtle-link')}</p><button class="primary" type="submit">提案を送信する</button><p id="form-result" role="status" aria-live="polite"></p></form></section></div>`}
const legal={about:['このサイトについて','高知の旅先を、みんなのおすすめと運営が選んだモデルコースから探すサイトです。','おすすめ票は実票のみを表示し、同票の場合は運営設定の初期順位で並べます。掲載申請は運営確認後に公開します。'],contact:['お問い合わせ','高知観光ランキング運営事務局への一般のお問い合わせは、下記メールアドレスへご連絡ください。','掲載のご提案は掲載追加申請、掲載情報の修正は情報修正申請をご利用ください。ご提案・修正内容は運営が確認後に対応します。'],terms:['利用規約','本規約は、高知観光ランキング運営事務局（以下「運営」といいます。）が運営する高知観光ランキング（以下「本サイト」といいます。）の利用条件を定めるものです。','本サイトの掲載情報、営業時間、料金、予約可否その他の内容は変更される場合があります。利用・予約の前に、必ず各施設・事業者の公式情報をご確認ください。','不正投票、不正アクセス、虚偽または誤認を招く申請、他者の権利・名誉・プライバシーを侵害する行為、本サイトの運営を妨げる行為を禁止します。','掲載提案および修正申請は、運営の判断で掲載・反映しない場合があります。運営は、確認した施設情報、修正情報その他の申請内容を、必要な範囲で本サイトに反映する場合があります。','本サイトの文章、写真、画像その他のコンテンツに関する著作権その他の権利は、運営または各権利者に帰属します。写真は各表示クレジットおよびライセンス条件に従って利用されています。無断転載・再利用はご遠慮ください。','本サイトからリンクする外部サイトの内容、提供サービス、個人情報の取扱いについて、運営は責任を負いません。外部サイトの規約・方針をご確認ください。','運営は、掲載情報の正確性、完全性、有用性、特定目的への適合性、サービスの継続性を保証しません。本サイトの利用または利用不能により生じた損害について、法令上認められる範囲で責任を負いません。','運営は、必要に応じて本規約を変更できます。変更後の規約は本サイトに掲載した時点から適用します。','本規約は日本法に準拠します。'],privacy:['プライバシーポリシー','高知観光ランキング運営事務局（以下「運営」といいます。）は、本サイトで取り扱う情報を適切に管理します。','本サイトは、投票状態の識別と不正利用防止のため、ブラウザーのlocalStorageに匿名IDを保存します。また、「行ってみたいスポット」と「保存したモデルコース」は利用中のブラウザー内にのみ保存し、サーバーへ送信しません。匿名IDは、投票対象スポットIDおよび投票記録とともに、ランキング集計、不正利用防止、サービス運営のために必要な期間保存します。','掲載提案では、施設名、カテゴリ、エリア、市町村、おすすめ理由のほか、任意で住所、公式サイト・SNS・地図URL、電話番号、メニュー、ニックネーム、メールアドレス、補足を取得します。修正申請では、対象スポット、修正対象、修正内容・確認元、任意メールアドレスを取得します。','取得した情報は、投票管理、不正利用防止、掲載提案・修正申請の審査、必要な連絡、サイト情報の改善・掲載のために利用します。メールアドレス等の個人情報を原則として一般公開しません。施設情報や修正内容は、確認後に本サイトへ反映する場合があります。','投票記録および申請情報は、Cloudflare WorkersおよびD1を利用して保存・処理します。掲載提案、修正申請および任意メールアドレスは、対応完了後1年を目安に削除します。','本サイトは現在、Google Analytics、広告、広告トラッキングを独自に実装していません。Cloudflare等のサービス提供事業者によるアクセスログ、Cookie、国外処理その他の取扱いは、各事業者の設定・方針により異なるため、本ポリシーではコードから確認できる範囲を超えて断定しません。','情報の開示、訂正、削除等のご希望は、本人確認等の必要な確認を行ったうえで、法令および合理的な範囲で対応します。お問い合わせは下記メールアドレスへご連絡ください。','未成年の方が本サイトを通じて情報を提供する場合、必要に応じて保護者の同意を求めることがあります。','運営は、必要に応じて本ポリシーを変更します。変更後のポリシーは本サイトに掲載した時点から適用します。']};
export const getRoutes=()=>['/','/courses/','/features/','/area/','/guide/',...Object.keys(categories).map(k=>`/${k}/`),'/events/',...events.map(e=>`/events/${esc(e.slug)}/`),...courses.map(c=>`/courses/${esc(c.slug)}/`),...spots.map(s=>`/spots/${s.slug}/`),...Object.keys(areas).map(k=>`/area/${k.replaceAll('_','-')}/`),'/suggest/','/correction/','/mypage/',...Object.keys(legal).map(k=>`/${k}/`),'/search/'];
